// Generated by Atlas Genesis (static-site template). Pure: turns site.json into
// pages, a sitemap and robots.txt with no file system or process access, so the
// same code builds dist/ here and renders the live preview on the hosted app.

/** Problems that stop a build, as plain sentences. Empty when site.json is usable. */
export function validateSite(site) {
  const problems = [];
  if (!site?.name) problems.push("site.json has no name");
  if (!site?.pages?.some((page) => page.id === "home")) problems.push("site.json needs a home page");
  for (const page of site?.pages ?? []) {
    if (!page.title || !page.headline) problems.push(`page ${page.id} needs a title and a headline`);
    if (!page.description || page.description.length > 160) problems.push(`page ${page.id} needs a description of at most 160 characters`);
  }
  return problems;
}

/**
 * @param {object} site  parsed site.json
 * @param {{ base?: string, year?: number }} [options]  base prefixes every internal link (a preview lives under a path)
 */
export function createRenderer(site, { base = "", year = new Date().getFullYear() } = {}) {
  const escape = (value) => String(value ?? "").replace(/[&<>"']/gu, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const fileFor = (page) => (page.id === "home" ? "index.html" : `${page.id}.html`);
  const homeHref = base || "/";
  const hrefFor = (page) => (page.id === "home" ? homeHref : `${base}/${page.id}.html`);
  // Canonical URLs and sitemap entries must be absolute. Set "url" in site.json to the live address; until then
  // they stay site-relative and the build says so.
  const origin = String(site.url ?? "").replace(/\/+$/u, "");
  const absolute = (page) => `${origin}${hrefFor(page)}`;
  // Structured data states only what site.json states: no address, phone, rating or hours are ever made up.
  const localBusiness = () => JSON.stringify({
    "@context": "https://schema.org",
    "@type": "LocalBusiness",
    name: site.name,
    ...(origin ? { url: origin } : {}),
    ...(site.contact.phone ? { telephone: site.contact.phone } : {}),
    ...(site.contact.email ? { email: site.contact.email } : {}),
    ...(site.location?.city ? { areaServed: { "@type": "City", name: [site.location.city, site.location.region].filter(Boolean).join(", ") } } : {}),
  }).replace(/</gu, "\\u003c");


  function section(block) {
    if (block.type === "cards") {
      return `<section class="band"><h2>${escape(block.title)}</h2><div class="cards">${block.items.map((item) => `<article class="card"><h3>${escape(item.title)}</h3><p>${escape(item.text)}</p></article>`).join("")}</div></section>`;
    }
    if (block.type === "steps") {
      return `<section class="band"><h2>${escape(block.title)}</h2><ol class="steps">${block.items.map((item) => `<li><strong>${escape(item.title)}</strong> ${escape(item.text)}</li>`).join("")}</ol></section>`;
    }
    if (block.type === "gallery") {
      return `<section class="band"><h2>${escape(block.title)}</h2><div class="gallery">${block.items.map((item) => `<figure class="tile"><div class="swatch" aria-hidden="true"></div><figcaption>${escape(item)}</figcaption></figure>`).join("")}</div><p class="note">${escape(block.note ?? "")}</p></section>`;
    }
    if (block.type === "contact") {
      return `<section class="band contact"><div><h2>${escape(block.title)}</h2><p>${escape(block.text)}</p><ul class="details">${site.contact.phone ? `<li>Phone: <a href="tel:${escape(site.contact.phone)}">${escape(site.contact.phone)}</a></li>` : ""}${site.contact.email ? `<li>Email: <a href="mailto:${escape(site.contact.email)}">${escape(site.contact.email)}</a></li>` : ""}${site.contact.area ? `<li>Service area: ${escape(site.contact.area)}</li>` : ""}</ul></div>
<form id="enquiry" class="card form" novalidate>
  <div class="field"><label for="name">Name *</label><input id="name" name="name" autocomplete="name" required></div>
  <div class="field"><label for="email">Email *</label><input id="email" name="email" type="email" autocomplete="email" required></div>
  <div class="field"><label for="phone">Phone</label><input id="phone" name="phone" type="tel" autocomplete="tel"></div>
  <div class="field"><label for="message">How can we help? *</label><textarea id="message" name="message" rows="4" required></textarea></div>
  <p class="form-error" id="enquiry-error" role="alert" hidden></p>
  <button type="submit">Send enquiry</button>
</form>
<div class="card success" id="enquiry-done" role="status" hidden><h3>Thank you!</h3><p>We received your message and will reply soon.</p></div></section>`;
    }
    return `<section class="band"><h2>${escape(block.title)}</h2>${(block.paragraphs ?? []).map((p) => `<p>${escape(p)}</p>`).join("")}</section>`;
  }

  function render(page) {
    const nav = site.pages.map((item) => `<a href="${hrefFor(item)}"${item.id === page.id ? ' aria-current="page"' : ""}>${escape(item.title)}</a>`).join("");
    const hasForm = page.sections.some((block) => block.type === "contact");
    return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escape(page.id === "home" ? `${site.name} · ${site.tagline}` : `${page.title} · ${site.name}`)}</title>
<meta name="description" content="${escape(page.description)}">
<link rel="canonical" href="${origin ? absolute(page) : hrefFor(page)}">
<meta property="og:title" content="${escape(page.title)} · ${escape(site.name)}">
<meta property="og:description" content="${escape(page.description)}">
<meta property="og:type" content="website">${page.id === "home" ? `\n<script type="application/ld+json">${localBusiness()}</script>` : ""}
<link rel="stylesheet" href="${base}/styles.css">${hasForm ? `\n<script type="module" src="${base}/contact.js"></script>` : ""}
</head>
<body>
<a class="skip" href="#main">Skip to content</a>
<header class="topbar"><a class="brand" href="${homeHref}">${escape(site.name)}</a><nav aria-label="Main">${nav}</nav></header>
<main id="main">
<section class="hero"><h1>${escape(page.headline)}</h1><p class="lead">${escape(page.intro)}</p>${page.id !== "contact" ? `<a class="button" href="${base}/contact.html">${escape(site.cta)}</a>` : ""}</section>
${page.sections.map(section).join("\n")}
</main>
<footer class="footer"><p>© ${year} ${escape(site.name)}${site.contact.area ? ` · ${escape(site.contact.area)}` : ""}</p></footer>
</body>
</html>
`;
  }


  const sitemap = () => `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${site.pages.map((page) => `  <url><loc>${escape(origin ? absolute(page) : hrefFor(page))}</loc></url>`).join("\n")}\n</urlset>\n`;
  const robots = () => `User-agent: *\nAllow: /\nSitemap: ${origin}/sitemap.xml\n`;
  return { origin, fileFor, hrefFor, render, sitemap, robots };
}
